const clamp01 = (x: number): number => (x < 0 ? 0 : x > 1 ? 1 : x);

/** Normalized 0..1 to real units. Clamps n; NaN counts as the neutral value. */
export function toReal(i: number, n: number): number {
  const d = DESCS[i];
  if (Number.isNaN(n)) return d.neutral;
  n = clamp01(n);
  const r = d.scale === 'log' ? d.min * Math.pow(d.max / d.min, n) : d.min + (d.max - d.min) * n;
  return Math.min(d.max, Math.max(d.min, r));
}

/** Real units to normalized, clamped to 0..1. NaN counts as the neutral value. */
export function toNorm(i: number, real: number): number {
  const d = DESCS[i];
  if (Number.isNaN(real)) real = d.neutral;
  if (d.scale === 'log') {
    if (!(real > 0)) return 0;
    return clamp01(Math.log(real / d.min) / Math.log(d.max / d.min));
  }
  return clamp01((real - d.min) / (d.max - d.min));
}

/** Every parameter at its neutral value, normalized. */
export function neutralSet(): Float32Array {
  const s = new Float32Array(COUNT);
  for (let i = 0; i < COUNT; i++) s[i] = toNorm(i, DESCS[i].neutral);
  return s;
}
